 const qaState=$('#qaState');if(qaState)qaState.textContent=parts.length?(qaBlocking?'Needs attention':'Checks passed'):'Waiting for parts';
 const qr=$('#qaReady'),qb=$('#qaBlocking'),qband=$('#qaBanding'),qu=$('#qaUnknownEdges');
 if(qr)qr.textContent=qaReady;if(qb)qb.textContent=qaBlocking;if(qband)qband.textContent=hasBanding?(bandingMm/1000).toFixed(2)+' m':'—';if(qu)qu.textContent=unknownEdges;
 const report=$('#qaReport');
 if(report)report.innerHTML=qaRows.length?qaRows.slice(0,80).map(r=>'<div class="qa-row"><div><strong>'+esc(r.id)+' · '+esc(r.name)+'</strong><small>'+esc(r.issues.join(' · '))+'</small></div><span class="'+(r.blocking?'qa-bad':'qa-warn')+'">'+(r.blocking?'BLOCK':'CHECK')+'</span></div>').join('')+(qaRows.length>80?'<p class="muted">Showing first 80 flagged rows of '+qaRows.length+'.</p>':''):'<p class="qa-good">No rule-based issues detected in the current rows. This does not certify drawing interpretation or cut-size correctness.</p>';
